#include <iostream>
#include <memory>

class Widget {
public:
    Widget() { std::cout << "Widget created" << std::endl; }
    ~Widget() { std::cout << "Widget destroyed" << std::endl; }
    void display() const { std::cout << "Displaying Widget" << std::endl; }
};

int main() {
    {
        auto widgetPtr = std::make_unique<Widget>(); // unique ownership
        widgetPtr->display();
    } // widgetPtr goes out of scope here, automatically destroying the Widget

    {
        auto sharedWidget = std::make_shared<Widget>(); // shared ownership
        auto anotherShared = sharedWidget; // reference count increases
        sharedWidget->display();
    } // both shared pointers go out of scope here, Widget destroyed when last shared_ptr is destroyed
    return 0;
}
